const languages=['en','zh-Hans','zh-Hant','fil','id','ms'];const selector=document.querySelector('#language');if(selector)selector.addEventListener('change',()=>{let parts=location.pathname.split('/').filter(Boolean);if(languages.includes(parts[0]))parts.shift();const prefix=selector.value==='en'?'':'/'+selector.value;location.assign(prefix+'/'+(parts.length?parts.join('/')+'/':'')+location.search+location.hash)});